// Qué se rompió, en un mensaje que se pueda leer desde el teléfono.
//
// El Error Trigger recibe la ejecución que falló entera. Lo que importa para
// decidir si hay que levantarse a arreglarlo es: qué workflow, qué nodo, y
// qué dijo el error — no el stack trace.
const entrada = $input.first().json || {};
const ejecucion = entrada.execution || {};
const workflow = entrada.workflow || {};
const error = ejecucion.error || entrada.error || {};

const nodo = ejecucion.lastNodeExecuted || (error.node && error.node.name) || 'desconocido';
const motivo = error.message || error.description || 'sin detalle';

// La URL de la ejecución es lo primero que se quiere abrir, así que va
// entera y no cortada.
const enlace = ejecucion.url || null;

const mensaje = [
  '🚨 El agente de WhatsApp falló',
  '',
  'Workflow: ' + (workflow.name || 'desconocido'),
  'Nodo: ' + nodo,
  'Error: ' + motivo,
  'Cuándo: ' + new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }),
]
  .concat(enlace ? ['', 'Ver la ejecución: ' + enlace] : [])
  .join('\n');

return [{ json: { mensaje, nodo, motivo, enlace, workflow: workflow.name || null } }];
